<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {Search,Refresh,Download} from '@element-plus/icons-vue'
import {usePageGuide} from '../spec/guide-context'
import type {GuideTopic} from '../spec/types'
import {stamp,voucherTemplateName,grantVoucherBenefit,grantVoucherType,voucherTypeLabels,voucherAssetSummary,voucherStatus,canRevokeVoucher,grantUsage,voucherUsageSummary,roleLabels,tone,progressKey,memberExpiryAt,memberStatus as effectiveMemberStatus,availableMemberBenefits,type Store,type Grant,type User,type InviteRecord} from '../model'
const props=defineProps<{store:Store;readonly:boolean;busy:boolean;now:number}>()
const emit=defineEmits<{retry:[grants:Grant[]];revoke:[grant:Grant];audit:[record:InviteRecord];export:[kind:string,rows:Record<string,string|number>[]]}>()
const tab=ref('assets'),filters=reactive({query:'',status:'',kind:'',activity:''}),applied=ref({...filters}),page=ref(1),size=ref(10),selected=ref<Grant[]>([])
const detailOpen=ref(false),detailGrant=ref<Grant|null>(null),detailUser=ref<User|null>(null),detailInvite=ref<InviteRecord|null>(null)
usePageGuide(()=>({topic:('records_'+tab.value) as GuideTopic,priority:10,detail:props.readonly?'只读：可查询和导出，不可执行运营写操作。':'查询与详情只读；核验、重试和撤回需要确认。'}))
usePageGuide(()=>detailOpen.value?{topic:detailUser.value?'asset_detail':detailGrant.value?'grant_detail':'invite_detail',priority:20,detail:detailGrant.value?'当前奖励：'+(detailGrant.value.kind==='member'?'会员':voucherTypeLabels[grantVoucherType(detailGrant.value)])+'；详情读取原快照，不随模板回写。':'当前详情只读；关闭返回来源列表。'}:null)
const memberStatus=(user:User)=>effectiveMemberStatus(props.store,user,props.now)
const memberExpiryText=(user:User)=>{const expiry=memberExpiryAt(props.store,user,props.now);return expiry===null?'—':props.store.memberPause?.users[user.id]!==undefined?'计时暂停 · 剩余'+((expiry-props.now)/86400000).toFixed(1)+'天':stamp(expiry)}
const userName=(id:string)=>props.store.users.find(u=>u.id===id)?.name??id
const userVouchers=(id:string)=>props.store.grants.filter(g=>g.userId===id&&g.kind==='voucher'&&g.status==='已发放')
const available=(id:string)=>userVouchers(id).filter(g=>voucherStatus(g,props.now)==='未使用')
const userInvites=(id:string)=>props.store.invites.filter(i=>i.inviterId===id&&i.status==='有效').length
const includes=(text:string)=>!applied.value.query||text.toLowerCase().includes(applied.value.query.toLowerCase())
const assets=computed(()=>props.store.users.filter(u=>includes(u.id+u.name+u.phone)&&(!applied.value.status||memberStatus(u)===applied.value.status)))
const invitations=computed(()=>props.store.invites.filter(i=>includes(i.id+i.inviterId+i.inviteeId+i.name+(i.activityResults??[]).map(r=>r.activityName).join(''))&&(!applied.value.status||i.status===applied.value.status)&&(!applied.value.activity||i.activityResults?.some(r=>r.activityId===applied.value.activity&&!['未命中','优先级排除'].includes(r.status)))))
const grants=computed(()=>props.store.grants.filter(g=>includes(g.id+g.userId+userName(g.userId)+g.eventId+(g.activityName??''))&&(!applied.value.status||g.status===applied.value.status)&&(!applied.value.kind||g.kind===applied.value.kind)&&(!applied.value.activity||g.activityId===applied.value.activity)))
const total=computed(()=>tab.value==='assets'?assets.value.length:tab.value==='invites'?invitations.value.length:grants.value.length)
const assetRows=computed(()=>assets.value.slice((page.value-1)*size.value,page.value*size.value)),inviteRows=computed(()=>invitations.value.slice((page.value-1)*size.value,page.value*size.value)),grantRows=computed(()=>grants.value.slice((page.value-1)*size.value,page.value*size.value))
const statuses=computed(()=>tab.value==='assets'?['未开通','有效会员','会员已停用','会员已失效','已过期']:tab.value==='invites'?['有效','不计奖','待核验']:['已发放','待发放','发放失败','人工处理','已撤回','已失效'])
const eligibleSelected=computed(()=>selected.value.filter(g=>['发放失败','待发放','人工处理'].includes(g.status)))
const visibleResults=(record:InviteRecord)=>(record.activityResults??[]).filter(r=>r.status!=='未命中')
const hasPending=(record:InviteRecord)=>record.status==='待核验'||record.activityResults?.some(r=>r.status==='待核验')
const userProgress=(id:string)=>props.store.config.activities.filter(a=>!a.archived).flatMap(a=>a.rewards.filter(r=>r.enabled||props.store.progress[progressKey(id,a.id,r.kind)]).map(r=>{const p=props.store.progress[progressKey(id,a.id,r.kind)];return {activity:a.name,kind:r.kind==='member'?'会员':'优惠券',count:p?.count??0,target:p?.target??r.target,state:a.enabled&&r.enabled?'累计中':'已暂停'}}))
function search(){applied.value={...filters};page.value=1;selected.value=[]}
function reset(){Object.assign(filters,{query:'',status:'',kind:'',activity:''});search()}
watch(()=>props.store.grants,()=>{selected.value=[]});watch(tab,reset);watch(total,()=>{if((page.value-1)*size.value>=total.value)page.value=Math.max(1,Math.ceil(total.value/size.value))})
function show(kind:string,row:Grant|User|InviteRecord){detailGrant.value=kind==='grant'?row as Grant:null;detailUser.value=kind==='user'?row as User:null;detailInvite.value=kind==='invite'?row as InviteRecord:null;detailOpen.value=true}
function exportRows(){const rows:Record<string,string|number>[]=tab.value==='assets'?assets.value.map(u=>({'用户编号':u.id,'姓名':u.name,'手机号':u.phone,'会员状态':memberStatus(u),'到期时间':memberExpiryText(u),'有效邀请':userInvites(u.id),'可用券张数':available(u.id).length})):tab.value==='invites'?invitations.value.map(i=>({'事件编号':i.id,'邀请人':i.inviterId,'新用户':i.inviteeId,'身份':roleLabels[i.role],'状态':i.status,'活动判定':(i.activityResults??[]).map(r=>r.activityName+'：'+r.status).join('；'),'原因':i.reason,'时间':stamp(i.at)})):grants.value.map(g=>({'发放单号':g.id,'用户':g.userId,'类型':g.kind==='member'?'会员':voucherTypeLabels[grantVoucherType(g)],'奖励':g.kind==='member'?g.months+'个月':grantVoucherBenefit(g),'状态':g.status,'来源活动':g.activityName??'—','活动编号':g.activityId??'—','来源事件':g.eventId,'规则快照':g.version,'原因':g.reason,'创建时间':stamp(g.createdAt)}));emit('export',tab.value,rows)}
</script>
<template>
 <section class="panel record-panel"><div class="panel-heading"><h2>用户资产与奖励记录</h2><el-tag type="info" size="small">本地演示数据</el-tag></div>
  <el-tabs v-model="tab" class="inner-tabs"><el-tab-pane label="用户资产" name="assets"/><el-tab-pane label="邀请明细" name="invites"/><el-tab-pane label="奖励发放" name="grants"/></el-tabs>
  <el-form inline class="filter-form" @submit.prevent="search"><el-form-item label="关键词"><el-input v-model="filters.query" :placeholder="tab==='assets'?'姓名 / 手机号 / 用户ID':'单号 / 用户ID / 来源事件'" clearable style="width:230px" @keyup.enter="search"/></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" placeholder="全部状态" clearable style="width:150px"><el-option v-for="s in statuses" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item v-if="tab!=='assets'" label="来源活动"><el-select v-model="filters.activity" placeholder="全部活动" clearable style="width:190px"><el-option v-for="a in store.config.activities.filter(a=>!a.archived)" :key="a.id" :value="a.id" :label="a.name"/></el-select></el-form-item><el-form-item v-if="tab==='grants'" label="奖励类型"><el-select v-model="filters.kind" placeholder="全部" clearable style="width:130px"><el-option value="member" label="会员"/><el-option value="voucher" label="优惠券"/></el-select></el-form-item><el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form>
  <div class="table-toolbar"><el-space><strong>{{tab==='assets'?'资产列表':tab==='invites'?'邀请列表':'发放列表'}} <span class="muted">{{total}} 条</span></strong><el-button v-if="tab==='grants'" type="primary" plain :disabled="readonly||!eligibleSelected.length" :loading="busy" @click="emit('retry',eligibleSelected)">批量重试（{{eligibleSelected.length}}）</el-button></el-space><el-button :icon="Download" :disabled="!total" @click="exportRows">导出当前筛选</el-button></div>
  <el-table v-if="tab==='assets'" :data="assetRows" border empty-text="没有匹配的用户，可调整筛选条件" row-key="id"><el-table-column label="用户" min-width="180"><template #default="{row}"><el-button type="primary" link @click="show('user',row)">{{row.name}}</el-button><div class="subline mono">{{row.id}} · {{row.phone}}</div></template></el-table-column><el-table-column label="身份" width="85"><template #default="{row}">{{roleLabels[row.role as User['role']]}}</template></el-table-column><el-table-column label="会员状态" width="105"><template #default="{row}"><el-tag :type="tone(memberStatus(row))">{{memberStatus(row)}}</el-tag></template></el-table-column><el-table-column label="会员到期时间" min-width="178"><template #default="{row}">{{memberExpiryText(row)}}</template></el-table-column><el-table-column label="累计有效邀请" width="114"><template #default="{row}">{{userInvites(row.id)}} 人</template></el-table-column><el-table-column label="可用优惠券" width="130"><template #default="{row}">{{available(row.id).length}} 张<div class="subline">{{voucherAssetSummary(available(row.id))}}</div></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button type="primary" link @click="show('user',row)">查看详情</el-button></template></el-table-column></el-table>
  <el-table v-else-if="tab==='invites'" :data="inviteRows" border empty-text="没有匹配的邀请记录"><el-table-column label="事件编号" prop="id" min-width="165" show-overflow-tooltip/><el-table-column label="邀请人" min-width="125"><template #default="{row}">{{userName(row.inviterId)}}<div class="subline mono">{{row.inviterId}}</div></template></el-table-column><el-table-column label="新用户 / 身份" min-width="170"><template #default="{row}">{{row.name}} · {{roleLabels[row.role as User['role']]}}<div class="subline mono">{{row.inviteeId}}</div></template></el-table-column><el-table-column label="活动判定" min-width="195"><template #default="{row}"><div v-for="r in visibleResults(row)" :key="r.activityId">{{r.activityName}} · {{r.status}}</div><span v-if="!row.activityResults?.length">—</span></template></el-table-column><el-table-column label="计数状态 / 原因" min-width="235"><template #default="{row}"><el-tag :type="tone(row.status)">{{row.status}}</el-tag><div class="subline">{{row.reason}}</div></template></el-table-column><el-table-column label="注册时间" min-width="180"><template #default="{row}">{{stamp(row.at)}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button type="primary" link @click="show('invite',row)">详情</el-button><el-button v-if="hasPending(row)" type="primary" link :disabled="readonly" @click="emit('audit',row)">核验处理</el-button></template></el-table-column></el-table>
  <el-table v-else :key="'grants-'+page+'-'+applied.status+'-'+store.seq" :data="grantRows" border row-key="id" empty-text="没有匹配的发放记录" @selection-change="(rows:Grant[])=>selected=rows"><el-table-column type="selection" width="45"/><el-table-column label="发放单号 / 来源事件" min-width="175"><template #default="{row}"><span class="mono">{{row.id}}</span><div class="subline mono">{{row.eventId}}</div></template></el-table-column><el-table-column label="获奖用户" min-width="115"><template #default="{row}">{{userName(row.userId)}}<div class="subline mono">{{row.userId}}</div></template></el-table-column><el-table-column label="来源活动" min-width="180"><template #default="{row}">{{row.activityName||'—'}}<div class="subline mono">{{row.activityId}}</div></template></el-table-column><el-table-column label="奖励 / 配置" min-width="130"><template #default="{row}">{{row.kind==='member'?row.months+'个月会员':voucherTypeLabels[grantVoucherType(row)]+' · '+grantVoucherBenefit(row)}}<div class="subline">{{row.version}}</div></template></el-table-column><el-table-column label="状态 / 说明" min-width="215"><template #default="{row}"><el-tag :type="tone(row.status)">{{row.status}}</el-tag><el-tag v-if="row.kind==='voucher'&&row.status==='已发放'" :type="tone(voucherStatus(row,now))" class="ml6">{{voucherStatus(row,now)}}</el-tag><div class="subline">{{row.reason}}</div></template></el-table-column><el-table-column label="创建时间" min-width="178"><template #default="{row}">{{stamp(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="162" fixed="right"><template #default="{row}"><el-button type="primary" link @click="show('grant',row)">详情</el-button><el-button v-if="['发放失败','待发放','人工处理'].includes(row.status)" type="primary" link :disabled="readonly||busy" @click="emit('retry',[row])">重试</el-button><el-button v-if="canRevokeVoucher(row,now)" type="danger" link :disabled="readonly" @click="emit('revoke',row)">撤回</el-button></template></el-table-column></el-table>
  <div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50]" :total="total" layout="total, sizes, prev, pager, next, jumper" @size-change="page=1;selected=[]"/></div>
 </section>
 <el-drawer v-model="detailOpen" :title="detailUser?'用户资产详情':detailGrant?'奖励发放详情':'邀请事件详情'" size="740px" :close-on-click-modal="true">
  <template v-if="detailUser"><el-descriptions :column="2" border><el-descriptions-item label="用户">{{detailUser.name}}</el-descriptions-item><el-descriptions-item label="用户ID">{{detailUser.id}}</el-descriptions-item><el-descriptions-item label="手机号">{{detailUser.phone}}</el-descriptions-item><el-descriptions-item label="账号状态">{{detailUser.blocked?'已冻结':'正常'}}</el-descriptions-item><el-descriptions-item label="会员状态">{{memberStatus(detailUser)}}</el-descriptions-item><el-descriptions-item label="到期时间">{{memberExpiryText(detailUser)}}</el-descriptions-item><el-descriptions-item label="可用会员权益" :span="2">{{availableMemberBenefits(store,detailUser,now).map(b=>b.name).join('、')||'暂无可用权益'}}</el-descriptions-item><el-descriptions-item label="累计有效邀请">{{userInvites(detailUser.id)}} 人</el-descriptions-item><el-descriptions-item label="可用优惠券">{{available(detailUser.id).length}} 张</el-descriptions-item></el-descriptions><h3 class="section-title">活动奖励进度</h3><el-table :data="userProgress(detailUser.id)" border empty-text="暂无活动进度"><el-table-column prop="activity" label="活动" min-width="190"/><el-table-column prop="kind" label="奖励" width="90"/><el-table-column label="当前轮次" width="120"><template #default="{row}">{{row.count}} / {{row.target}}</template></el-table-column><el-table-column prop="state" label="状态" width="100"/></el-table><h3 class="section-title">优惠券资产</h3><el-table :data="userVouchers(detailUser.id)" border><el-table-column prop="id" label="券发放单号" min-width="160"/><el-table-column label="类型 / 抵用内容" min-width="155"><template #default="{row}">{{voucherTypeLabels[grantVoucherType(row)]}}<div class="subline">{{grantVoucherBenefit(row)}}</div></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="tone(voucherStatus(row,now))">{{voucherStatus(row,now)}}</el-tag></template></el-table-column><el-table-column label="有效期" min-width="185"><template #default="{row}">{{stamp(row.issuedAt)}}<div class="subline">至 {{stamp(row.expiresAt)}}</div></template></el-table-column></el-table></template>
  <template v-else-if="detailGrant"><el-descriptions :column="1" border><el-descriptions-item label="发放单号">{{detailGrant.id}}</el-descriptions-item><el-descriptions-item label="幂等发放键"><span class="mono break">{{detailGrant.key}}</span></el-descriptions-item><el-descriptions-item label="用户">{{userName(detailGrant.userId)}} · {{detailGrant.userId}}</el-descriptions-item><el-descriptions-item label="来源 / 配置">{{detailGrant.source}} / {{detailGrant.version}}</el-descriptions-item><el-descriptions-item label="来源活动">{{detailGrant.activityName||'—'}} · {{detailGrant.activityId||'—'}}</el-descriptions-item><el-descriptions-item label="奖励快照">{{detailGrant.kind==='member'?detailGrant.months+'个月会员':(detailGrant.template?voucherTemplateName(detailGrant.template):'优惠券')+' · '+voucherTypeLabels[grantVoucherType(detailGrant)]+' · '+grantVoucherBenefit(detailGrant)}}</el-descriptions-item><el-descriptions-item v-if="detailGrant.kind==='voucher'" label="本券用券规则"><template v-if="grantUsage(detailGrant)">{{grantUsage(detailGrant)!.orderScope.join('、')}}<div class="subline">{{voucherUsageSummary(grantUsage(detailGrant)!,grantVoucherType(detailGrant))}}</div></template><span v-else>历史记录未保存用券规则</span></el-descriptions-item><el-descriptions-item label="状态 / 说明"><el-tag :type="tone(detailGrant.status)">{{detailGrant.status}}</el-tag><div class="mt8">{{detailGrant.reason}}</div></el-descriptions-item><el-descriptions-item label="尝试次数">{{detailGrant.attempts}}</el-descriptions-item><el-descriptions-item label="创建时间">{{stamp(detailGrant.createdAt)}}</el-descriptions-item><el-descriptions-item label="到账时间">{{detailGrant.issuedAt?stamp(detailGrant.issuedAt):'尚未到账'}}</el-descriptions-item><el-descriptions-item v-if="detailGrant.kind==='voucher'" label="有效期">{{detailGrant.issuedAt?stamp(detailGrant.issuedAt):'发放成功后计算'}} 至 {{detailGrant.expiresAt?stamp(detailGrant.expiresAt):'—'}}</el-descriptions-item><el-descriptions-item v-if="detailGrant.usedAt" label="使用时间">{{stamp(detailGrant.usedAt)}}</el-descriptions-item><el-descriptions-item v-if="detailGrant.kind==='member'" label="本笔会员权益段">{{detailGrant.memberStart?stamp(detailGrant.memberStart):'尚未发放'}} 至 {{detailGrant.memberEnd?stamp(detailGrant.memberEnd):'—'}}</el-descriptions-item></el-descriptions><el-alert class="mt20" title="重试沿用本单快照及唯一发放键；会员关闭后失效的旧权益不能通过重试恢复。已使用券及已生效会员不提供直接撤回入口。" type="info" :closable="false"/></template>
  <template v-else-if="detailInvite"><el-descriptions :column="1" border><el-descriptions-item label="事件编号">{{detailInvite.id}}</el-descriptions-item><el-descriptions-item label="邀请人">{{detailInvite.inviterId}}</el-descriptions-item><el-descriptions-item label="新用户唯一ID">{{detailInvite.inviteeId}}</el-descriptions-item><el-descriptions-item label="注册身份">{{roleLabels[detailInvite.role]}}</el-descriptions-item><el-descriptions-item label="事件时间">{{stamp(detailInvite.at)}}</el-descriptions-item><el-descriptions-item label="规则快照">{{detailInvite.version}}</el-descriptions-item><el-descriptions-item label="状态 / 原因">{{detailInvite.status}} · {{detailInvite.reason}}</el-descriptions-item></el-descriptions><h3 class="section-title">逐活动判定</h3><el-table :data="detailInvite.activityResults??[]" border><el-table-column prop="activityName" label="活动名称" min-width="160"/><el-table-column prop="status" label="判定" width="110"/><el-table-column prop="reason" label="原因" min-width="250"/></el-table></template>
 </el-drawer>
</template>
